function useCountUp(target, duration = 1100, trigger = 0) {
  const [val, setVal] = useState(0);
  const [punch, setPunch] = useState(false);
  const startRef = useRef(null);
  useEffect(() => {
    startRef.current = null; let raf;
    const step = (ts) => {
      if (!startRef.current) startRef.current = ts;
      const p = Math.min(1, (ts - startRef.current) / duration);
      setVal(target * (1 - Math.pow(1 - p, 3)));
      if (p < 1) raf = requestAnimationFrame(step);
      else { setPunch(true); setTimeout(() => setPunch(false), 260); }
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target, duration, trigger]);
  return [val, punch];
}
function HeatGauge({ pct, color = ORANGE, colorSoft = AMBER }) {
  const clamped = Math.min(pct, 100);
  const r = 84, circumference = 2 * Math.PI * r * (270 / 360);
  const needleAngle = -135 + (clamped / 100) * 270;
  return (
    <svg viewBox="0 0 220 190" style={{ width: 220, maxWidth: "100%" }}>
      <defs>
        <linearGradient id="heatGrad" x1="0%" y1="100%" x2="100%" y2="0%"><stop offset="0%" stopColor={colorSoft} /><stop offset="100%" stopColor={color} /></linearGradient>
        <radialGradient id="dialShade" cx="50%" cy="35%" r="70%"><stop offset="0%" stopColor="rgba(255,255,255,0.07)" /><stop offset="100%" stopColor="rgba(0,0,0,0.25)" /></radialGradient>
        <filter id="glow"><feGaussianBlur stdDeviation="5" result="blur" /><feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge></filter>
        <filter id="dialDepth" x="-30%" y="-30%" width="160%" height="160%"><feDropShadow dx="0" dy="3" stdDeviation="4" floodColor="#000" floodOpacity="0.5" /></filter>
      </defs>
      <circle cx="110" cy="112" r="98" fill="url(#dialShade)" opacity="0.6" />
      <path d="M 42 158 A 84 84 0 1 1 178 158" fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="13" strokeLinecap="round" filter="url(#dialDepth)" />
      <path d="M 42 158 A 84 84 0 1 1 178 158" fill="none" stroke="url(#heatGrad)" strokeWidth="12" strokeLinecap="round" filter="url(#glow)" className="gauge-breathe"
        strokeDasharray={`${(clamped/100)*circumference} ${circumference}`} style={{ transition: "stroke-dasharray 1.1s cubic-bezier(.22,1,.36,1)" }} />
      <circle cx={110 + 68 * Math.sin((needleAngle * Math.PI) / 180)} cy={112 - 68 * Math.cos((needleAngle * Math.PI) / 180)} r="4" fill={INK} style={{ transition: "cx 1.1s cubic-bezier(.22,1,.36,1), cy 1.1s cubic-bezier(.22,1,.36,1)" }} />
      <text x="110" y="104" textAnchor="middle" fontSize="36" fontWeight="700" fill={INK} fontFamily="'Inter', sans-serif" letterSpacing="-0.02em">{clamped.toFixed(0)}%</text>
      <text x="110" y="123" textAnchor="middle" fontSize="10.5" fill={MUTED} letterSpacing="1.5">OBJECTIF 2026</text>
    </svg>
  );
}
